/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.css3;import page2020.view.Value;public class C3padding extends C3box {	public static final class Attr {		public static final String padding = "padding";	}	public Value padding(String shorthand) {		return new Value().name(Attr.padding).text(shorthand);	}	public Value padding(String side, String pixels) {		return new Value().name(Attr.padding + "-" + side).text(pixels);	}	public Value top(String pixels) {		return new Value().name(Attr.padding + "-top").text(pixels);	}	public Value right(String pixels) {		return new Value().name(Attr.padding + "-right").text(pixels);	}	public Value bottom(String pixels) {		return new Value().name(Attr.padding + "-bottom").text(pixels);	}	public Value left(String pixels) {		return new Value().name(Attr.padding + "-left").text(pixels);	}	public Value auto() {		return new Value().name(Attr.padding).text("auto");	}	public Value autoLeft() {		return new Value().name(Attr.padding + "-left").text("auto");	}	public Value autoRight() {		return new Value().name(Attr.padding + "-right").text("auto");	}}